// The configuration without its display-only keys, which change how a review reads and never what a check finds, so a
// change to one reuses the run. `language` joins them when it lands.
function decisive(config: MelianConfig): unknown {
	const { output: _, publish, ...rest } = config;
	const { emoji: __, ...kept } = publish;
	return { ...rest, publish: kept };
}

const missed = comparison.externalFinding(id);
if (
	fields.verdict === "valid" &&
	missed !== undefined &&
	!comparison.effectiveMatches().some((match) => match.external === id)
)
	return await (await CloneEvidence.open(io, stored.changeset.repoRoot)).keep(
		harness,
		stored.changeset.revision,
		missed,
	);

const stub = (needsReason: boolean, melian: string[] = []) =>
	({
		needsReason: () => needsReason,
		render: () => "",
		melianFindings: () => melian,
		externalFinding: () => undefined,
	}) as unknown as Comparison;

it("keeps nothing for a valid Melian finding or a match, which are not misses", () => {
	const { repo, env, external, melianId, evidence } = compared([8]);
	expect(melian(repo, valid(external(8)), env).stdout).not.toContain("evidence");
	expect(melian(repo, ["compare", "adjudicate", range, melianId, "--verdict", "valid"], env).stdout).not.toContain(
		"evidence",
	);
	expect(stored(evidence)).toEqual([]);
});

async keep(harness: CompareHarness, revision: Revision, finding: ExternalFinding): Promise<number> {
	const { id } = finding;
	const owned = await harness.ownedRun(revision);
	if (owned === undefined) {
		this.io.stdout(
			`Kept no evidence for ${id}: this clone holds no record of its round's run. An Actions round's records went with its job, and rerunning ${short(revision.head)} on a host gives a new conversation, not the original.\n`,
		);
		return 0;
	}
